-- *** _HOLD (2026-08-07): SLICE B of RFC_016 — do NOT apply in a blanket --apply run. ***
-- Council 902a8563 REJECTED shipping this alongside Slice A (guardian veto on
-- breadth). It applies only after: Slice A (327+329, applied 2026-08-07) has been
-- observed on real plan rows, this slice has its OWN council round, and a human
-- has read the v4 prompt plaintext (compliance seat's ask; 330 only). To apply:
-- rename away the _HOLD suffix, psql -f, then --record-only under the new name.
-- 330 — page-content-writer: prompt v4, per-section verified-facts scoping.
--
-- bugs_open/151 candidate 1, config half 3 of 3 (328 wiring, 329 planner prompt,
-- 330 writer prompt). One edit to generate_content's prompt_template: the
-- Verified Facts block becomes a three-way branch on the loop item --
--
--   facts_scoped + assigned_writer_block  -> that block, marked "assigned to
--                                            THIS section", with an explicit
--                                            "do NOT restate other facts" rule
--   facts_scoped + empty block            -> "state NO business numbers or
--                                            named-entity claims here"
--   not facts_scoped                      -> the site-wide writer_block,
--                                            byte-identical to today
--
-- Built from the LIVE template dumped 2026-08-06 (NOT from the v3 file in the
-- brochure lane sql dir, which is stale against live by two later patches: the
-- 241 voice placeholder and the 178 edit-mode block -- PBP-035's exact warning).
-- The new template ships as base64 and is written with jsonb_set/to_jsonb, so
-- no psql quoting can corrupt it (the v3 README records why: string literals
-- and \copy FROM PROGRAM both mangled braces/newlines). Plaintext copy for
-- review: docs/agent_docs/docs024_key_docs_latest/brochure_component_library/
-- sql/page_content_writer_prompt_v4_2026-08-06.txt
--
-- *** DO NOT APPLY until a chassis image carrying the Go half is LIVE *** --
-- the template renderer is missingkey=zero, so on an OLD binary the new
-- branches read absent keys as falsy and fall through to the site-wide block
-- (today's behaviour, no error); but items can never be scoped without the Go
-- half, so applying early buys nothing. Pod check as in 328.

SELECT snapshot_agent('page-content-writer', '330_page_content_writer_prompt_v4_scoped_facts.sql: pre-update');

BEGIN;

CREATE TABLE IF NOT EXISTS agent_definitions_bak_330 AS
SELECT id, type, default_config, now() AS backed_up_at
FROM agent_definitions
WHERE type = 'page-content-writer' AND is_active
  AND COALESCE(is_snapshot, false) = false AND deleted_at IS NULL;

-- Pre-check: the row exists, v4 is not already applied, and the LIVE template
-- still carries the anchor block v4 replaces (drift = re-derive v4 from live).
DO $$
DECLARE
    t text;
BEGIN
    SELECT default_config->'workflow'->'steps'->'process_sections_loop'->'config'
           ->'sub_workflow'->'steps'->'generate_content'->'config'->>'prompt_template'
    INTO t
    FROM agent_definitions
    WHERE type = 'page-content-writer' AND is_active
      AND COALESCE(is_snapshot, false) = false AND deleted_at IS NULL;

    IF t IS NULL THEN
        RAISE EXCEPTION '330: page-content-writer generate_content prompt_template not found';
    END IF;
    IF position('facts_scoped' in t) > 0 THEN
        RAISE EXCEPTION '330: already applied -- facts_scoped branch present';
    END IF;
    IF position('{{if .site_specs.specs.evidence_base}}{{if .site_specs.specs.evidence_base.writer_block}}' in t) = 0 THEN
        RAISE EXCEPTION '330: live template has drifted -- the evidence_base block v4 replaces is absent; re-derive v4 from the live row';
    END IF;
END $$;

UPDATE agent_definitions
SET default_config = jsonb_set(
        default_config,
        '{workflow,steps,process_sections_loop,config,sub_workflow,steps,generate_content,config,prompt_template}',
        to_jsonb(convert_from(decode(
'',
        'base64'), 'UTF8'))
    ),
    updated_at = NOW()
WHERE type = 'page-content-writer' AND is_active
  AND COALESCE(is_snapshot, false) = false AND deleted_at IS NULL;

-- Verify: the branch is present, the fallback (site-wide) block survives, and
-- the em-dash census is unchanged from the live template this was built from
-- (5 -- all in pre-existing rule text; the v3-era count of 3 belonged to the
-- body that still inlined the voice block).
DO $$
DECLARE
    t text;
    dashes int;
BEGIN
    SELECT default_config->'workflow'->'steps'->'process_sections_loop'->'config'
           ->'sub_workflow'->'steps'->'generate_content'->'config'->>'prompt_template'
    INTO t
    FROM agent_definitions
    WHERE type = 'page-content-writer' AND is_active
      AND COALESCE(is_snapshot, false) = false AND deleted_at IS NULL;

    IF position('{{if .current_section.facts_scoped}}' in t) = 0
       OR position('assigned to THIS section' in t) = 0
       OR position('No verified facts are assigned to this section' in t) = 0
       OR position('{{if .site_specs.specs.evidence_base.writer_block}}' in t) = 0
       OR position('{{.voice_style}}' in t) = 0 THEN
        RAISE EXCEPTION '330: verify failed -- a required branch or the preserved fallback/voice placeholder is missing';
    END IF;
    dashes := length(t) - length(replace(t, '—', ''));
    IF dashes <> 5 THEN
        RAISE EXCEPTION '330: verify failed -- em-dash census is % not 5; the template was corrupted in transit or built from a stale base', dashes;
    END IF;
END $$;

COMMIT;

